pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(uint16 feeRateInput) public {
        vm.assume(feeRateInput <= 5000);

        address baseToken = address(0);
        address nft = address(0x1234);
        uint128 virtualBaseTokenReserves = 1 ether;
        uint128 virtualNftReserves = 1e18;
        uint56 changeFee = 1;
        bytes32 merkleRoot = bytes32(0);
        bool useStolenNftOracle = false;
        bool payRoyalties = false;

        bool ok;
        try c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRateInput,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.feeRate() == feeRateInput);
        } else {
            assertTrue(false);
        }
    }
}
